mapper.select:
select t.object_name,t.object_name objectName,t.eo_id,t.eo_id eoId,t.remark,t.status_cd,t.status_cd
statusCd,t.state,t.rule_id,t.rule_id ruleId,t.community_id,t.community_id communityId,t.obj_type,t.obj_type
objType,t.object_id,t.object_id objectId,td.name objTypeName
from event_object t
left join t_dict td on t.obj_type = td.status_cd and td.table_name = 'event_object' and td.table_columns = 'obj_type'
where 1 =1

    and t.object_name= #{objectName}


    and t.eo_id= #{eoId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.state= #{state}


    and t.rule_id= #{ruleId}


    and t.community_id= #{communityId}


    and t.obj_type= #{objType}


    and t.object_id= #{objectId}

order by t.create_time desc

    limit #{page}, #{row}

